      "howto": "① 예측 탭에서 무역풍이 약해질 때의 변화를 먼저 예측해요.\n② 실험 탭: **무역풍의 세기** 슬라이더를 움직이거나 **엘니뇨·평상시·라니냐** 버튼을 눌러요.\n적도 태평양 단면에서 따뜻한 해수층, 수온 약층의 깊이, 해수면 높이, 상승 기류의 위치와 **동태평양 수온 편차**를 관찰해요.\n**실제 자료로 맞춰 보기**로 1997~98, 2015~16 엘니뇨와 2010~11, 2020~21 라니냐를 불러와 비교해요.\n③ 미션 탭의 도전 과제를 모두 달성해 보세요.",
      "concept": "평상시에는 무역풍이 따뜻한 표층 해수를 서쪽으로 밀어 서태평양은 따뜻하고 동태평양에서는 용승이 일어납니다.\n**엘니뇨**는 무역풍이 약해져 동태평양의 용승이 약해지고 표층 수온이 평상시보다 높아지는 현상입니다.\n**라니냐**는 무역풍이 강해져 동태평양의 용승이 강해지고 수온이 평상시보다 낮아지는 현상입니다.",
      "inquiry": "엘니뇨 시기에 동태평양 연안의 강수량과 어획량은 어떻게 변할까?\n라니냐 시기에 서태평양의 기압은 평상시보다 높을까, 낮을까?",
