      "concept": "**수평 퇴적의 법칙**: 지층은 처음에 수평으로 쌓입니다.\n**지층 누중의 법칙**: 지층이 역전되지 않았다면 아래 지층이 먼저 쌓였습니다.\n**관입의 법칙**: 관입한 화성암은 관입당한 암석보다 나중에 생겼습니다.\n**부정합의 법칙**: 부정합면 위아래 지층 사이에는 긴 시간 간격이 있습니다.",
      "inquiry": "기울어진 지층 위에 수평한 지층이 있다면 어떤 일이 있었을까?\n관입암과 그 주변 지층 중 어느 것이 먼저 생겼는지 어떻게 알 수 있을까?",
