      "howto": "**표면 온도** 슬라이더를 움직이거나 베텔게우스·태양·베가·리겔 버튼을 누릅니다.\n**현재 곡선 남기기**로 여러 온도의 곡선을 겹쳐 비교하고, **지우기**로 지웁니다.",
      "concept": "별은 흑체에 가까워 온도에 따라 복사 에너지 분포가 달라집니다.\n**빈의 변위 법칙**(λmax = 2.898×10⁻³/T): 온도가 높을수록 최대 에너지를 방출하는 파장이 짧아져 별이 파랗게 보입니다.\n**슈테판·볼츠만 법칙**(E = σT⁴): 온도가 높을수록 단위 면적에서 방출하는 에너지가 매우 많아집니다.",
      "inquiry": "표면 온도가 2배가 되면 최대 복사 파장과 단위 면적당 에너지는 어떻게 변할까?\n붉은 별과 파란 별 중 표면 온도가 높은 별은?",
