      "concept": "허블은 은하를 모양에 따라 **타원 은하(E)**, **나선 은하(S, SB)**, **불규칙 은하(Irr)**로 분류했습니다.\n타원 은하는 늙은 별이 많아 붉고 성간 물질이 적으며, 나선 은하의 나선팔과 불규칙 은하에는 성간 물질이 많아 젊고 푸른 별이 많습니다.\n나선 은하는 Sa → Sc로 갈수록 팽대부가 작고 나선팔이 느슨해집니다. 우리은하는 막대 나선 은하입니다.",
