      "howto": "",
      "concept": "확산: 물질이 농도가 높은 쪽에서 낮은 쪽으로 퍼져 나가는 현상. 산소, 이산화 탄소처럼 작은 분자는 세포막을 쉽게 통과한다.\n삼투: 반투과성 막을 사이에 두고 용질의 농도가 낮은 쪽에서 높은 쪽으로 물이 이동하는 현상.\n저장액(세포 안보다 묽은 용액): 물이 들어와 적혈구는 부풀다 터지고(용혈), 식물 세포는 팽팽해진다(팽윤).\n고장액(세포 안보다 진한 용액): 물이 빠져나가 적혈구는 쪼그라들고, 식물 세포는 세포막이 세포벽에서 떨어진다(원형질 분리).",
      "inquiry": "적혈구를 증류수에 넣으면 어떻게 되나요? 그 까닭을 물의 이동으로 설명해 보세요.\n양파 표피세포는 증류수에 넣어도 터지지 않습니다. 동물 세포와 무엇이 달라서일까요?\n20 % 설탕물에 넣은 양파 표피세포에서 원형질 분리가 일어나는 까닭은?\n세포막 통과 실험에서 설탕 분자가 막을 통과하지 못하는 것은 세포막의 어떤 성질 때문일까요?",
