      "status": "ready",
      "height": 0,
      "howto": "",
      "concept": "물질대사: 생명체에서 일어나는 모든 화학 반응. 생명체 밖의 반응(예: 연소)과 달리 체온 정도의 온도에서 여러 단계로 천천히 에너지를 내놓는다.\n활성화 에너지: 반응이 일어나는 데 필요한 최소한의 에너지. 효소는 활성화 에너지를 낮춰 반응이 빠르게 일어나게 한다.\n효소는 반응 전후에 변하지 않아 여러 번 다시 쓰인다.\n효소는 특정한 기질에만 작용한다(기질 특이성). 효소의 활성 부위와 기질의 모양이 맞아야 한다.",
      "inquiry": "효소를 넣으면 에너지 그래프의 어느 부분이 바뀌나요? 반응물과 생성물의 에너지 차이도 바뀌나요?\n과산화 수소수에 감자 조각과 생간 조각을 넣었을 때 생기는 기체는 무엇일까요? 불씨로 어떻게 확인할 수 있나요?\n효소 공장에서 아밀레이스로 지방을 분해할 수 없는 까닭은 무엇인가요?\n우리 생활에서 효소를 이용한 사례를 하나 골라 카드 뉴스로 소개해 보세요.",
