      "howto": "",
      "concept": "유전자: DNA에서 특정 단백질을 만드는 정보가 담긴 부분.\n전사: 핵 안에서 DNA 한 가닥(주형 가닥)에 상보적인 염기를 가진 RNA가 만들어진다. RNA에는 T 대신 U가 있다.\n번역: RNA가 세포질로 나와 라이보솜에 결합하면, 코돈(3염기)이 지정하는 아미노산이 차례로 연결되어 폴리펩타이드가 된다.\n폴리펩타이드가 접히고 꼬여 고유한 입체 구조를 가진 단백질이 되고, 단백질이 형질을 나타낸다.",
      "inquiry": "DNA 주형 가닥이 TAC라면 RNA 코돈과 아미노산은 무엇일까요?\n염기 1개나 2개로는 20여 가지 아미노산을 모두 지정할 수 없는 까닭을 계산으로 설명해 보세요.\n돌연변이 실험에서 헤모글로빈 유전자의 7번째 코돈 GAG가 GUG로 바뀌면 어떤 아미노산이 바뀌나요? 이것이 낫 모양 적혈구와 어떤 관계가 있을까요?\n염기가 바뀌었는데도 아미노산이 바뀌지 않는 경우가 있을까요? 코돈표에서 찾아보세요.",
