      "concept": "묽은 염산에는 H⁺과 Cl⁻이, 수산화 나트륨 수용액에는 Na⁺과 OH⁻이 들어 있다.\n두 용액을 섞으면 H⁺ + OH⁻ → H₂O 반응이 일어난다. Na⁺과 Cl⁻은 반응하지 않고 그대로 남는다.\n중화 반응이 일어날 때 열(중화열)이 발생해 용액의 온도가 높아진다.\n반응한 H⁺과 OH⁻이 많을수록, 즉 생성된 물이 많을수록 온도가 더 많이 올라간다.\nH⁺이 남으면 산성(BTB 노란색), OH⁻이 남으면 염기성(파란색), 둘 다 없으면 중성(초록색)이다.",
