      "concept": "생산자는 광합성으로 빛에너지를 유기물 속 화학 에너지로 바꾼다.\n먹이 관계를 따라 에너지가 1차, 2차, 3차 소비자로 전달된다. 먹이사슬이 얽혀 먹이그물을 이룬다.\n각 영양단계는 받은 에너지의 대부분을 생명 활동에 쓰고 열로 내보내며, 일부(약 10 %)만 다음 단계로 전달한다.\n그래서 상위 영양단계로 갈수록 에너지양, 개체수, 생물량이 줄어드는 생태피라미드를 이룬다.\n에너지는 순환하지 않고 한 방향으로 흐르다가 결국 열로 생태계를 빠져나간다.",
