      "height": 0,
      "howto": "",
      "concept": "초식동물이 늘면 풀이 줄고, 먹이가 부족해진 초식동물은 다시 줄어든다.\n초식동물이 늘면 육식동물도 늘고, 늘어난 육식동물에게 먹혀 초식동물이 줄어든다.\n이처럼 먹고 먹히는 관계에 따라 개체수가 늘고 줄기를 반복하다가 일정한 범위에서 유지된다. 이것이 생태계평형이다.\n육식동물이 없으면 초식동물이 지나치게 늘어 풀이 크게 줄어든다(과도한 방목).\n사람의 활동(밀렵, 서식지 파괴)이 지나치면 평형이 깨지고 회복에 오랜 시간이 걸린다.",
      "inquiry": "밀렵만 막고 육식동물을 들여오지 않으면 풀과 초식동물은 어떻게 변하나요? 그 까닭은 무엇인가요?\n육식동물을 너무 일찍(초식동물이 적을 때) 들여오면 어떤 일이 생기나요?\n그래프에서 초식동물의 봉우리와 육식동물의 봉우리는 어느 쪽이 먼저 나타나나요? 그 까닭을 설명해 보세요.\n자유 실험에서 가뭄을 일으키면 평형이 깨졌다가 다시 회복되나요? 회복되는 데 몇 년쯤 걸리나요?\n생태계평형을 지키기 위해 우리 지역에서 할 수 있는 일을 제안해 보세요.",
      "added": "2026-10-14",
