      "concept": "지구로 들어온 태양 복사 에너지 중 약 30 %는 반사되고, 약 70 %가 지표와 대기에 흡수된다.\n지표는 흡수한 에너지를 파장이 긴 지구 복사 에너지로 방출한다.\n수증기, 이산화 탄소, 메테인 같은 온실 기체는 지구 복사 에너지를 흡수했다가 일부를 지표로 다시 방출(재복사)한다.\n이 때문에 대기가 없을 때보다 지표의 온도가 높게 유지된다. 이것이 온실 효과이다.\n온실 기체가 늘면 우주로 나가는 에너지가 줄어 열수지가 +가 되고, 온도가 올라 다시 평형을 이룰 때까지 지구가 더워진다(지구 온난화).",
