      "concept": "적도는 태양 에너지를 많이 받아 공기가 데워져 상승하고, 구름과 비가 많다(저압대).\n상승한 공기는 고위도로 이동하다가 위도 30° 부근에서 하강한다. 하강하는 공기는 데워지며 건조해져 구름이 생기기 어렵다(고압대).\n그래서 위도 30° 부근에는 사하라, 아라비아, 오스트레일리아 사막처럼 큰 사막이 많다.\n사막화는 사막 주변 지역이 점점 사막처럼 변하는 현상이다. 대기 대순환의 변화로 강수량이 줄어드는 자연적 원인과 과잉 방목, 과잉 경작, 삼림 벌채 같은 인위적 원인이 함께 작용한다.",
