      "concept": "지구 평균 기온의 상승 폭은 지금까지 배출한 이산화 탄소의 누적량에 거의 비례한다.\n그래서 배출량을 빨리 줄일수록 누적량이 적어져 기온 상승을 낮게 억제할 수 있다.\n탄소 중립: 배출하는 온실 기체와 흡수·제거하는 양을 같게 만들어 순배출량을 0으로 만드는 것. 우리나라는 2050년 탄소 중립을 목표로 한다.\n완화(원인 줄이기): 재생 에너지, 에너지 효율, 수송 전기화, 숲 복원, 탄소 포집.\n적응(피해 줄이기): 방재 시설, 폭염 대비, 농작물 품종 개량 등.",
