      "concept": "태양 중심부는 온도가 약 1500만 K, 압력이 매우 높아 수소 원자핵이 서로 반발력을 이기고 충돌한다.\n수소 원자핵 4개가 단계적으로 융합해 헬륨 원자핵 1개가 된다(수소 핵융합).\n반응 후 질량이 약 0.7 % 줄어들고, 줄어든 질량(질량 결손)만큼 에너지가 생긴다(E = mc²).\n이 에너지가 빛의 형태로 지구에 도달해 광합성, 물의 순환, 대기의 순환을 일으킨다.\n화석 연료, 바람, 수력, 생물 에너지는 모두 태양 에너지가 형태를 바꾼 것이다. 반면 지열, 조력, 원자력은 태양에서 온 것이 아니다.",
      "inquiry": "온도를 500만 K로 낮추면 핵융합이 거의 일어나지 않습니다. 그 까닭을 원자핵의 전하와 관련지어 설명해 보세요.\n수소 원자핵 4개의 질량과 헬륨 원자핵 1개의 질량을 비교하고, 차이만큼의 질량은 어떻게 되었는지 설명해 보세요.\n석탄이 태양 에너지에서 유래했다고 말할 수 있는 까닭은 무엇인가요?\n조력 발전과 지열 발전의 에너지는 각각 어디에서 왔나요?\n태양 에너지가 지구에서 전환되는 흐름을 ‘태양 → 광합성 → … ’처럼 하나 골라 이어 써 보세요.",
