      "inquiry": "태양광 발전소만 지었을 때 그래프에서 어느 시간대에 전기가 부족한가요? 그 까닭은 무엇인가요?\n풍력 발전소를 들판보다 산 능선이나 바다에 지을 때 발전량이 많은 까닭은 무엇일까요?\nESS를 지으면 그래프가 어떻게 달라지나요? ESS 자체가 전기를 만드는 것은 아닌데도 필요한 까닭을 설명해 보세요.\n내가 설계한 마을의 장점과 한계를 비용, 안정성, 환경 측면에서 평가해 보세요.\n우리 지역의 지형과 기후에 가장 알맞은 신재생 에너지는 무엇일지 근거를 들어 제안해 보세요.",
