      "howto": "",
      "concept": "감염병은 세균이나 바이러스 같은 병원체가 몸에 침입해 생기는 질병이다.\n신속 항원 검사: 검체 속 병원체의 단백질(항원)이 키트 속 항체와 결합하면 검사선(T)에 색이 나타난다. 빠르지만 바이러스가 많을 때만 검출된다.\nPCR 검사: 병원체의 핵산을 수없이 복제(증폭)해 아주 적은 양도 찾아낸다. 가장 정확하지만 시간이 오래 걸린다.\n항체 검사: 감염된 뒤 몸이 만든 항체를 혈액에서 찾는다. 항체가 생기기까지 시간이 걸려 초기 진단에는 알맞지 않다.\n빠르고 정확한 진단으로 감염자를 찾아 격리하면 감염병의 확산을 막을 수 있다.",
      "inquiry": "감염 1일째에는 세 검사 결과가 어떻게 나오나요? 감염되었는데도 음성이 나오는 까닭을 설명해 보세요.\n신속 항원 검사가 양성으로 나오는 기간과 PCR 검사가 양성으로 나오는 기간을 비교해 보세요.\n감염 20일째에 PCR은 음성인데 항체 검사가 양성이라면 무엇을 뜻할까요?\n선별 진료소 게임에서 예산과 시간이 부족할 때 어떤 전략으로 검사를 골랐나요?\n감염병 진단 기술 외에 감염병 확산을 막는 데 쓰이는 과학기술(추적, 백신, 빅데이터 등)을 조사해 보세요.",
