      "concept": "인공지능은 사람의 학습, 추론 능력을 컴퓨터로 구현한 기술이다. 인공지능 로봇은 주변을 인식하고 스스로 판단해 움직인다.\n기계 학습에서는 정답이 붙은 많은 데이터(학습 데이터)에서 규칙을 스스로 찾는다.\n학습에 쓰지 않은 새 데이터(시험 데이터)로 얼마나 잘 맞히는지 확인해 성능을 평가한다.\n학습 데이터가 한쪽으로 치우치면(편향) 인공지능은 처음 보는 경우를 틀리기 쉽다. 이름표가 틀려도 잘못 배운다.\n그래서 다양하고 정확한 데이터를 모으고, 인공지능의 판단을 사람이 점검하는 것이 중요하다(인공지능 윤리).",
